import { Metadata } from "next";

const siteUrl =
  process.env.NEXT_PUBLIC_SITE_URL || "https://inject3r.github.io";
const basePath = process.env.NEXT_PUBLIC_BASE_PATH || "/ip-address-database";

export const dynamic = "force-dynamic";

interface ASNDetailLayoutProps {
  children: React.ReactNode;
  params:
    | Promise<{ countryCode: string; asn: string }>
    | { countryCode: string; asn: string };
}

export async function generateMetadata({
  params,
}: ASNDetailLayoutProps): Promise<Metadata> {
  const resolvedParams = await Promise.resolve(params);
  const { countryCode, asn } = resolvedParams;
  const asnPath = `${basePath}/asn/${countryCode.toLowerCase()}/${asn}`;

  return {
    title: `AS${asn} Network Record | ${countryCode.toUpperCase()}`,
    description: `View AS${asn} network ranges, organization metadata, and IPv4/IPv6 allocations for ${countryCode.toUpperCase()}.`,
    keywords: [
      `AS${asn}`,
      `${countryCode} ASN lookup`,
      `AS${asn} network ranges`,
      `IPv4 IPv6 AS${asn}`,
      `autonomous system data`,
    ],
    alternates: {
      canonical: `${siteUrl}${asnPath}/`,
    },
    openGraph: {
      title: `AS${asn} Network Record | ${countryCode.toUpperCase()}`,
      description: `Detailed network and routing data for AS${asn} in ${countryCode.toUpperCase()}.`,
      type: "website",
      url: `${siteUrl}${asnPath}/`,
      siteName: "IP Address Database",
      locale: "en_US",
    },
    twitter: {
      card: "summary_large_image",
      title: `AS${asn} Network Record | ${countryCode.toUpperCase()}`,
      description: `Detailed routing and network information for AS${asn}.`,
      creator: "@inject3r",
    },
  };
}

export default function ASNDetailLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return <>{children}</>;
}
